import SwiftUI

extension SwiftForgeTheme {

    /// Calm and deep: lagoon-teal accents on sea-foam surfaces, with
    /// pebble-rounded corners (14-pt controls, 22-pt cards).
    ///
    /// Depth comes from soft, wide shadows tinted with the deep-sea navy of
    /// the dark canvas, so raised surfaces float rather than stand out.
    /// Controls are taller than in ``forge`` and headings are set lighter,
    /// which gives screens an unhurried rhythm; motion is slow and settles
    /// without bounce. Status colors stay clearly apart from the teal
    /// accent: reef blue for information, kelp green for success.
    public static let ocean: SwiftForgeTheme = {
        typealias P = Palette.Ocean
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.Lagoon.s600, dark: P.Lagoon.s300, lightHighContrast: P.Lagoon.s800, darkHighContrast: P.Lagoon.s200),
            onSolid: SwiftForgeColor(light: Palette.white, dark: P.abyss, darkHighContrast: Palette.black),
            text: SwiftForgeColor(
                light: P.Lagoon.s700, dark: P.Lagoon.s300, lightHighContrast: P.Lagoon.s800, darkHighContrast: P.Lagoon.s200),
            subtle: SwiftForgeColor(
                light: P.Lagoon.s50, dark: P.Lagoon.s950, lightHighContrast: P.Lagoon.s100, darkHighContrast: P.Lagoon.s900))
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.foam, dark: P.abyss),
            surface: SwiftForgeColor(light: Palette.white, dark: P.deep),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.trench),
            fillMuted: SwiftForgeColor(
                light: P.Tide.s100, dark: P.Tide.s900, lightHighContrast: P.Tide.s200, darkHighContrast: P.Tide.s800),
            textPrimary: SwiftForgeColor(
                light: P.ink, dark: P.pearl, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Tide.s700, dark: P.Tide.s300, lightHighContrast: P.Tide.s800, darkHighContrast: P.Tide.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Tide.s200, dark: P.Tide.s800, lightHighContrast: P.Tide.s400, darkHighContrast: P.Tide.s600),
            borderStrong: SwiftForgeColor(
                light: P.Tide.s500, dark: P.Tide.s500, lightHighContrast: P.Tide.s700, darkHighContrast: P.Tide.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Tide.s800, dark: P.Tide.s300, lightHighContrast: P.Tide.s900, darkHighContrast: P.Tide.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.abyss, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Tide.s700, dark: P.Tide.s300, lightHighContrast: P.Tide.s800, darkHighContrast: P.Tide.s200),
                subtle: SwiftForgeColor(
                    light: P.Tide.s100, dark: P.Tide.s900, lightHighContrast: P.Tide.s200, darkHighContrast: P.Tide.s800)),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Reef.s700, dark: P.Reef.s300, lightHighContrast: P.Reef.s800, darkHighContrast: P.Reef.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.abyss, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Reef.s700, dark: P.Reef.s300, lightHighContrast: P.Reef.s800, darkHighContrast: P.Reef.s200),
                subtle: SwiftForgeColor(
                    light: P.Reef.s50, dark: P.Reef.s950, lightHighContrast: P.Reef.s100, darkHighContrast: P.Reef.s900)),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Kelp.s700, dark: P.Kelp.s300, lightHighContrast: P.Kelp.s800, darkHighContrast: P.Kelp.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.abyss, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Kelp.s700, dark: P.Kelp.s300, lightHighContrast: P.Kelp.s800, darkHighContrast: P.Kelp.s200),
                subtle: SwiftForgeColor(
                    light: P.Kelp.s50, dark: P.Kelp.s950, lightHighContrast: P.Kelp.s100, darkHighContrast: P.Kelp.s900)),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Sand.s300, dark: P.Sand.s300, lightHighContrast: P.Sand.s400, darkHighContrast: P.Sand.s200),
                onSolid: SwiftForgeColor(
                    light: P.ink, dark: P.abyss, lightHighContrast: Palette.black, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Sand.s700, dark: P.Sand.s300, lightHighContrast: P.Sand.s800, darkHighContrast: P.Sand.s200),
                subtle: SwiftForgeColor(
                    light: P.Sand.s50, dark: P.Sand.s950, lightHighContrast: P.Sand.s100, darkHighContrast: P.Sand.s900)),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Coral.s700, dark: P.Coral.s300, lightHighContrast: P.Coral.s800, darkHighContrast: P.Coral.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.abyss, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Coral.s700, dark: P.Coral.s300, lightHighContrast: P.Coral.s800, darkHighContrast: P.Coral.s200),
                subtle: SwiftForgeColor(
                    light: P.Coral.s50, dark: P.Coral.s950, lightHighContrast: P.Coral.s100, darkHighContrast: P.Coral.s900))
        )
        return SwiftForgeTheme(
            id: "ocean",
            displayName: "Ocean",
            colors: colors,
            typography: SwiftForgeTypography.standard
                .updating([\.largeTitle, \.title1, \.title2]) { $0.weight = .medium }
                .updating([\.title3, \.headline]) { $0.weight = .medium },
            spacing: SwiftForgeSpacing(
                xxxs: 2, xxs: 4, xs: 8, sm: 12, md: 16, lg: 22, xl: 28, xxl: 36, xxxl: 48,
                screenHorizontal: 20, section: 28, component: 12, cardPadding: 20
            ),
            radius: SwiftForgeRadius(
                xs: 4, sm: 8, md: 12, lg: 16, xl: 22, xxl: 32,
                control: 14, controlSmall: 10, card: 22, sheet: 32
            ),
            sizes: SwiftForgeSizes(
                minimumHitTarget: 44, controlHeightSmall: 36, controlHeightRegular: 48, controlHeightLarge: 56,
                iconSmall: 16, iconRegular: 20, iconLarge: 24
            ),
            elevation: SwiftForgeElevation(
                low: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Tide.s950, 0.08, dark: Palette.black, 0.45), radius: 8, y: 2),
                medium: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Tide.s950, 0.10, dark: Palette.black, 0.55), radius: 24, y: 8),
                high: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Tide.s950, 0.14, dark: Palette.black, 0.65), radius: 48, y: 18),
                raisedSurfacesHaveBorder: false
            ),
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.24),
                standard: SwiftForgeMotionToken(duration: 0.38),
                emphasized: SwiftForgeMotionToken(duration: 0.52),
                shimmerDuration: 2.0,
                pressedScale: 0.98
            ),
            components: SwiftForgeComponentTokens(
                card: SwiftForgeCardTokens(pressEffect: .scale(0.99)),
                banner: SwiftForgeBannerTokens(cornerRadius: 16),
                progress: SwiftForgeProgressTokens(barHeight: 6, barHeightLarge: 10),
                segmentedControl: SwiftForgeSegmentedControlTokens(indicatorInset: 4),
                slider: SwiftForgeSliderTokens(trackHeight: 6, thumbDiameter: 28),
                toast: SwiftForgeToastTokens(cornerRadius: 20),
                dialog: SwiftForgeDialogTokens(cornerRadius: 28)
            )
        )
    }()
}
